import {createAssetLibrary} from './assets.js';
import {blendJointPose,createClipMixer} from './animation.js';
import {controlledCapsule} from './physics.js';
import {QUALITY} from './performance.js';
/** Asset-independent skinned actor factory v1. Caller supplies GLB URL and rig/visual policy. */
export async function createActorFactory(runtime,{url,pose=null,clips={idle:'Idle',walk:'Walk',run:'Walk'},palette={},collider={height:1.8,radius:.35},ragdoll=false,strideSpeed=1.6}={}){
 if(!url)throw Error('Actor factory requires a model URL');const{B,scene}=runtime,assets=runtime.assets||createAssetLibrary(runtime),container=await assets.load(url),actors=new Set(),materials=new Map();let serial=0,ragCount=0,disposed=false;
 function instanceMaterial(original,variant){const colors=palette[original.name];if(!colors)return original;const hex=Array.isArray(colors)?colors[variant%colors.length]:colors,key=original.name+hex;if(!materials.has(key)){const m=original.clone(key);if(m.albedoColor)m.albedoColor=B.Color3.FromHexString(hex);else m.diffuseColor=B.Color3.FromHexString(hex);materials.set(key,m);}return materials.get(key);}
 function create({side=0,variant=side,scale=1}={}){if(disposed)throw Error('Actor factory disposed');const prefix='actor'+(++serial)+':',entry=container.instantiateModelsToScene(n=>prefix+n,false,{doNotInstantiate:true}),root=new B.TransformNode(prefix+'controller',scene),skel=entry.skeletons[0],nodes={},rest={},meshes=[];if(!skel){entry.dispose();root.dispose();throw Error('Actor model must contain a skeleton');}for(const n of entry.rootNodes)n.parent=root;for(const bone of skel.bones){const n=bone.getTransformNode();if(!n)continue;nodes[bone.name]=n;rest[bone.name]={position:n.position.asArray(),rotation:n.rotationQuaternion?.clone()||B.Quaternion.Identity()};}
 for(const n of root.getDescendants())if(n.getTotalVertices?.()){meshes.push(n);n.isPickable=false;n.receiveShadows=true;if(n.material)n.material=instanceMaterial(n.material,variant);runtime.shadows?.addShadowCaster(n);}root.scaling.setAll(scale);const capsule=controlledCapsule(runtime,{...collider,name:prefix+'capsule',height:collider.height*scale,radius:collider.radius*scale}),mixer=pose?null:createClipMixer(entry.animationGroups,clips);if(pose)entry.animationGroups.forEach(g=>g.stop());let rag=null,recovering=false,actorDisposed=false;
 function endRagdoll(){if(!rag)return;const poses=new Map(skel.bones.map(b=>[b.name,{p:b.getPosition(B.Space.LOCAL),q:b.getRotationQuaternion(B.Space.LOCAL)}]));rag.dispose();rag=null;ragCount--;for(const bone of skel.bones){const n=nodes[bone.name],p=poses.get(bone.name);if(!n)continue;if(p){n.position.copyFrom(p.p);n.rotationQuaternion=p.q.clone();}bone.linkTransformNode(n);}recovering=true;}
 function knockdown(impulse={x:0,y:1,z:0}){if(rag)return true;if(!ragdoll||ragCount>=(QUALITY[runtime.quality]?.ragdolls||3))return false;const config=typeof ragdoll==='function'?ragdoll({B,nodes,scale}):ragdoll;root.computeWorldMatrix(true);try{rag=new B.Ragdoll(skel,meshes[0],config);rag.ragdoll();ragCount++;for(let i=0;i<config.length;i++){const a=rag.getAggregate(i);a.shape.filterMembershipMask=8;a.shape.filterCollideMask=1;a.body.setLinearDamping(.2);a.body.setAngularDamping(.6);a.body.setLinearVelocity(new B.Vector3(impulse.x,impulse.y,impulse.z));}return true;}catch(e){rag?.dispose();rag=null;throw Error('Ragdoll configuration failed: '+e.message);}}
 const actor={root,nodes,rest,meshes,skel,get ragdoll(){return !!rag;},knockdown,endRagdoll,update(state,dt){if(rag&&state.recover)endRagdoll();if(!rag){root.position.set(state.x||0,state.y||0,state.z||0);root.rotation.y=state.angle||0;root.scaling.setAll(state.scale??scale);if(pose||recovering){const targets=pose?pose(state,rest):{};blendJointPose(B,nodes,targets,rest,dt,{responsiveness:recovering?6:14});}else{mixer.set(state.state||'idle',state.animationSpeed??(['walk','run'].includes(state.state)?Math.max(.25,(state.speedNow||strideSpeed)/(strideSpeed*(state.scale??scale))):1));mixer.update(dt);mixer.sample(state.animationProgress,{exclusive:!!state.animationExclusive});}if(recovering&&!state.recover)recovering=false;}capsule.move(state.x||0,(state.y||0)+collider.height*(state.scale??scale)/2,state.z||0);},shadows(){for(const m of meshes)runtime.shadows?.addShadowCaster(m);},dispose(){if(actorDisposed)return;actorDisposed=true;if(rag){rag.dispose();rag=null;ragCount--;}capsule.dispose();mixer?.dispose();entry.dispose();root.dispose();actors.delete(actor);}};actors.add(actor);return actor;}
 return{create,get ragCount(){return ragCount;},get size(){return actors.size;},dispose(){if(disposed)return;disposed=true;for(const a of [...actors])a.dispose();if(!runtime.assets)assets.dispose();for(const m of materials.values())m.dispose();}};
}
